// One email listing the week's checked changes. Sends nothing in a week with no changes.
const s = $('Your settings').first().json;
const want = String(s.tools || '').split(',').map(t => t.trim().toLowerCase()).filter(Boolean);
const since = new Date(Date.now() - Number(s.days || 7) * 86400000).toISOString().slice(0, 10);
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const list = ($input.first().json.items || []).filter(c => c.date >= since
  && (want.length === 0 || want.includes(c.tool) || want.includes(String(c.tool_name).toLowerCase())));
if (list.length === 0) return [];
const rows = list.map(c => {
  const link = c.our_page.replace('utm_source=ail_feed', 'utm_source=n8n').replace('utm_medium=json', 'utm_medium=template_digest');
  return `<li><strong>${esc(c.tool_name)}</strong> (${esc(c.date)}): ${esc(c.summary)} <a href="${esc(link)}">More</a></li>`;
}).join('');
const html = `<p>${list.length} checked change(s) to AI tools' data terms since ${since}:</p><ul>${rows}</ul><p style="color:#666;font-size:12px">Source: AI Leakage (aileakage.com), CC BY 4.0. General information, not legal advice.</p>`;
return [{ json: { subject: `AI tool changes this week: ${list.length}`, html, send_to: s.send_to } }];
